\begin{restatable}[\textbf{\update{When are two variables always dependent in pure observational data?}}]{lemma}{LEMINDUCEDINPZERO}\label{lem:induced_in_p0}
    For any $i,j \in [D]$, $X_i$ and $X_j$ are adjacent in $\mathcal{M}_{\Gcal^{(\varnothing)}}$, if and only if $i$ and $j$ are adjacent in $\Gcal$, or $\ch_\Gcal(i) \cap \ch_\Gcal(j) \cap \anc_\Gcal(S) \neq \varnothing$, i.e., they involve in a same selection, or have a common child that is ancestrally selected.\looseness=-1
\end{restatable}

The adjacencies in~\cref{lem:induced_in_p0} reflect additional dependencies due to selection bias (\cref{lem:additional_dependencies_in_p0}). Furthermore, interventions can introduce even more dependencies, as shown in~\cref{lem:even_more_dependencies_in_pk}--again, recall the pest control example. We now generalize~\cref{lem:induced_in_p0} to characterize all these dependencies.


\begin{restatable}[\textbf{\update{When are two variables always dependent under an intervention?}}]{lemma}{LEMINDUCEDINPK}\label{lem:induced_in_pk}
    For any $i,j \in [D]$, $X_i$ and $X_j$ are adjacent in $\mathcal{M}_{\Gcal^{(I)}}$, if and only if $X_i$ and $X_j$ are adjacent in the observational MAG $\mathcal{M}_{\Gcal^{(\varnothing)}}$, or there exists a path between $X_i$ and $X_j$ in $\mathcal{M}_{\Gcal^{(\varnothing)}}$, where all non-endpoint vertices are affected (i.e., in $\des_\Gcal(I)$), and they, together with $i,j$, are all ancestrally selected (i.e., in $\anc_\Gcal(S)$).
\end{restatable}

Further generalizing the adjacencies in~\cref{lem:induced_in_pk} to the indicator variable $\zeta$, we have:

\begin{restatable}[\textbf{\update{When does an intervention alters all of a variable's conditional distributions?}}]{lemma}{LEMINDUCEDINTARGET}\label{lem:induced_in_target}
    For any $j \in [D]$, $\zeta$ and $X_j$ are adjacent in $\mathcal{M}_{\Gcal^{(I)}}$, if and only if $j$ is directly targeted (i.e., $j \in I$), or $j$ is both indirectly affected and ancestrally selected (i.e., $j \in  \des_\Gcal(I) \cap   \anc_\Gcal(S)$).
\end{restatable}

\cref{lem:induced_in_target} implies the unidentifiability of direct intervention targets when they are unknown. This is different from the case without selection, where ``unknown target is no longer a challenge'' (\cref{subsec:revisit}).


After constructing the adjacencies of $\mathcal{M}_{\Gcal^{(I)}}$ in~\cref{lem:induced_in_p0,lem:induced_in_pk,lem:induced_in_target}, we conclude with edge orientations:


\begin{restatable}[\textbf{\update{MAG of interventional twin graphs}}]{lemma}{LEMORIENTMAG}\label{lem:orient_mag}
    The MAG $\mathcal{M}_{\Gcal^{(I)}}$ consists of the following edges:
\begin{itemize}[noitemsep,topsep=0pt,left=10pt]
    \item ``Pseudo'' direct intervention target edges (by~\cref{lem:induced_in_target}): $\{\zeta \rightarrow X_i\}_{i \in I \cup (\des_\Gcal(I) \cap   \anc_\Gcal(S))}$;
    \item Edges among $X$. Let $\mathcal{M}_\Gcal$ be the MAG of $\Gcal$ over $[D]$. For each adjacent $X_i, X_j$ (by~\cref{lem:induced_in_pk}):
    \begin{itemize}[noitemsep,topsep=0pt,left=5pt]
    \item If $i\rightarrow j$ is in the original MAG $\mathcal{M}_\Gcal$, then orient $X_i\rightarrow X_j$ in interventional MAG $\mathcal{M}_{\Gcal^{(I)}}$;
    \item Otherwise (i.e., $i\text{ --- } j \in \mathcal{M}_\Gcal$ or $i, j$ are not adjacent in $\mathcal{M}_\Gcal$):
    \begin{itemize}[noitemsep,topsep=0pt,left=5pt]
    \item If $i \not\in \des_\Gcal(I)$ and $j \not\in \des_\Gcal(I)$: orient $X_i \text{ --- } X_j$;
    \item If $j \in \des_\Gcal(I)$ and ($i \not\in \des_\Gcal(I)$ or $i \in \anc_\Gcal(j)$): orient $X_i \rightarrow X_j$;
    \item If $i \in \des_\Gcal(I)$ and ($j \not\in \des_\Gcal(I)$ or $j \in \anc_\Gcal(i)$): orient $X_j \rightarrow X_i$;
    \item Otherwise, i.e., both $i,j \in \des_\Gcal(I)$, but neither is another's ancestor: orient $X_i \leftrightarrow X_j$.
\begin{restatable}[\textbf{Graphical criteria for Markov equivalence}]{theorem}{THMGRAPHICALCRITERIAEQUIVALENCE}\label{thm:graphical_criteria_for_markov_equivalence}

    For two DAGs $\Gcal$ and $\Hcal$ with two collections of targets $\Ical=\{I^{(0)},I^{(1)},\cdots,I^{(K)}\}$ and $\Jcal=\{J^{(0)},J^{(1)},\cdots,J^{(K)}\}$, the Markov equivalence $(\Gcal, \Ical) \sim (\Hcal, \Jcal) $ holds, if and only if for each $k =0,1,\cdots,K$, the corresponding MAGs of interventional twin graphs, $\mathcal{M}_{\Gcal^{I^{(k)}}}$ and $\mathcal{M}_{\Hcal^{J^{(k)}}}$, have the same adjacencies and v-structures\footnote{\update{Another condition for general MAG equivalence is not needed here, due to twin graphs' specific structures.}}.\looseness=-1
\end{restatable}

